values.headerCss:
.first-tier {
  height: 80px;
  margin-bottom: 0px;
}

.first-tier .nav>li>a {
  margin-top: 5px;
  padding: 3px 6px;
}

.first-tier .nav>li>a:focus,
.first-tier .nav>li>a:hover {
  background-color: #136fbf;
  color: #fff;
}

.first-tier .site-logo img {
  vertical-align: middle;
}

.first-tier h1 {
  display: inline;
  font-size: 25px;
}

.second-tier {
  margin-bottom: 0px;
}

values.footerCss:
.footer-background {
  padding-top: 20px;
  padding-bottom: 20px;
  background-color: #e7e7e7;
}

.logo, .nav {
  margin-bottom: 10px;
}

.nav-pills {
    display: flex;
    justify-content: center;
}
